input.command:
cd /tmp && export OPAMROOT=/root/.opam && eval $(opam env --switch=cc); cat > /tmp/hello.c <<'EOF'
#include <stdio.h>
int fib(int n){return n<2?n:fib(n-1)+fib(n-2);}
int main(){printf("hello compcert fib(10)=%d\n", fib(10)); return 0;}
EOF
/tmp/CompCert/ccomp -o /tmp/hello /tmp/hello.c 2>&1 && /tmp/hello; echo "run_exit=$?"
